1	package com.example.starter.service;
2	
3	import java.time.Instant;
4	import java.time.temporal.ChronoUnit;
5	import java.util.ArrayList;
6	import java.util.LinkedHashMap;
7	import java.util.List;
8	import java.util.Map;
9	import java.util.concurrent.ThreadLocalRandom;
10	import java.util.stream.Collectors;
11	
12	import org.springframework.stereotype.Service;
13	import org.springframework.transaction.annotation.Transactional;
14	
15	import com.example.starter.domain.AlertEvent;
16	import com.example.starter.domain.AlertType;
17	import com.example.starter.domain.Allocation;
18	import com.example.starter.domain.CurtailOrder;
19	import com.example.starter.domain.DispatchCycle;
20	import com.example.starter.domain.ExecutionReport;
21	import com.example.starter.domain.IdempotentRecord;
22	import com.example.starter.domain.LateReportEvent;
23	import com.example.starter.domain.OrderStatus;
24	import com.example.starter.domain.Turbine;
25	import com.example.starter.dto.AllocationItem;
26	import com.example.starter.dto.AlertView;
27	import com.example.starter.dto.OrderDetailResponse;
28	import com.example.starter.dto.OrderReceiveRequest;
29	import com.example.starter.dto.OrderReceiveResponse;
30	import com.example.starter.dto.ReportRequest;
31	import com.example.starter.dto.ReportResponse;
32	import com.example.starter.dto.SettleResponse;
33	import com.example.starter.repo.DispatchRepository;
34	import com.example.starter.repo.IdempotentRepository;
35	import com.example.starter.repo.TurbineRepository;
36	import com.example.starter.support.Fingerprints;
37	import com.example.starter.support.ServiceClock;
38	import com.example.starter.web.ApiBadRequestException;
39	import com.example.starter.web.ApiConflictException;
40	import com.example.starter.web.ApiNotFoundException;
41	import com.fasterxml.jackson.core.JsonProcessingException;
42	import com.fasterxml.jackson.databind.ObjectMapper;
43	
44	/**
45	 * 限电指令流转服务：接收分摊、新旧指令原子切换、执行回报去重、
46	 * 下发满 10 分钟未达标告警并按最新可用出力重分摊、日结封存。
47	 */
48	@Service
49	public class DispatchService {
50	
51	    /** 下发后达标判定时长：恰满 10 分钟即触发判定。 */
52	    static final long DUE_MINUTES = 10;
53	
54	    private final ServiceClock clock;
55	    private final TurbineRepository turbineRepository;
56	    private final DispatchRepository dispatchRepository;
57	    private final IdempotentRepository idempotentRepository;
58	    private final ObjectMapper objectMapper;
59	
60	    public DispatchService(ServiceClock clock,
61	                           TurbineRepository turbineRepository,
62	                           DispatchRepository dispatchRepository,
63	                           IdempotentRepository idempotentRepository,
64	                           ObjectMapper objectMapper) {
65	        this.clock = clock;
66	        this.turbineRepository = turbineRepository;
67	        this.dispatchRepository = dispatchRepository;
68	        this.idempotentRepository = idempotentRepository;
69	        this.objectMapper = objectMapper;
70	    }
71	
72	    /**
73	     * 接收限电指令：加风场行锁串行化同风场并发接收；新指令生效与旧指令作废在同一事务完成。
74	     */
75	    @Transactional
76	    public OrderReceiveResponse receive(OrderReceiveRequest request) {
77	        Instant now = clock.now();
78	        String fingerprint = Fingerprints.sha256(
79	                "ORDER|" + request.requestId() + "|" + request.farmCode() + "|" + request.targetPowerKw());
80	
81	        // 行锁前先处理确定的重放/冲突；未命中的并发情况在锁后二次确认。
82	        IdempotentRecord existing = idempotentRepository.findByRequestId(request.requestId());
83	        if (existing != null) {
84	            return resolveOrderIdempotent(existing, fingerprint);
85	        }
86	
87	        if (!turbineRepository.lockFarmRow(request.farmCode())) {
88	            throw new ApiBadRequestException("风场不存在：" + request.farmCode());
89	        }
90	
91	        existing = idempotentRepository.findByRequestId(request.requestId());
92	        if (existing != null) {
93	            return resolveOrderIdempotent(existing, fingerprint);
94	        }
95	
96	        List<Turbine> turbines = turbineRepository.findByFarm(request.farmCode());
97	        int farmAvailable = turbines.stream().mapToInt(Turbine::getAvailablePowerKw).sum();
98	
99	        CurtailOrder active = dispatchRepository.findActiveOrder(request.farmCode());
100	
101	        // 同一风场同一接收时刻只允许一个执行中指令：与执行中指令同时刻到达的并发接收冲突 409，
102	        // 保证并发接收唯一受理；早于当前时刻存在的旧指令视为先后到达，由新指令原子切换。
103	        if (active != null && !active.getReceivedAt().isBefore(now)) {
104	            throw new ApiConflictException(
105	                    "风场同一时刻已有执行中限电指令：" + active.getOrderNo());
106	        }
107	
108	        // 先落幂等占位（唯一约束兜底并发受理），再做业务写入。
109	        IdempotentRecord record = new IdempotentRecord();
110	        record.setRequestId(request.requestId());
111	        record.setBizType("ORDER");
112	        record.setFingerprint(fingerprint);
113	        record.setCreatedAt(now);
114	        record.setResponseBody("");
115	        if (!idempotentRepository.tryInsert(record)) {
116	            IdempotentRecord winner = idempotentRepository.findByRequestId(request.requestId());
117	            return resolveOrderIdempotent(winner, fingerprint);
118	        }
119	
120	        List<Allocation> allocations =
121	                AllocationEngine.allocate(turbines, request.targetPowerKw(), 0L, 1);
122	
123	        CurtailOrder order = new CurtailOrder();
124	        order.setOrderNo(generateOrderNo(now));
125	        order.setFarmCode(request.farmCode());
126	        order.setRequestId(request.requestId());
127	        order.setFingerprint(fingerprint);
128	        order.setTargetPowerKw(request.targetPowerKw());
129	        order.setStatus(OrderStatus.DISPATCHED);
130	        order.setCurrentCycleNo(1);
131	        order.setReceivedAt(now);
132	        // 先以非执行中插入拿 id，旧指令作废后再置执行中，避免唯一索引出现双 Y。
133	        long newId = dispatchRepository.insertOrder(order);
134	        allocations.forEach(a -> a.setOrderId(newId));
135	
136	        if (active != null) {
137	            // 同一事务：旧指令作废（active 释放）→ 新指令生效，不存在双指令同时生效窗口。
138	            dispatchRepository.markSuperseded(active.getId(), newId);
139	        }
140	        dispatchRepository.insertCycle(buildCycle(newId, 1, now));
141	        dispatchRepository.insertAllocations(newId, 1, allocations);
142	        // 旧指令已在本事务作废（active 释放），此处将新指令置为执行中。
143	        dispatchRepository.activateOrder(newId);
144	
145	        OrderReceiveResponse response = buildReceiveResponse(
146	                order, turbines, allocations, farmAvailable, false);
147	        idempotentRepository.updateRefAndResponse(request.requestId(), newId, toJson(response));
148	        return response;
149	    }
150	
151	    private OrderReceiveResponse resolveOrderIdempotent(IdempotentRecord existing, String fingerprint) {
152	        if (!existing.getFingerprint().equals(fingerprint)) {
153	            throw new ApiConflictException("相同 requestId 的业务参数与首次请求不一致");
154	        }
155	        if (existing.getResponseBody() != null && !existing.getResponseBody().isBlank()) {
156	            return fromJson(existing.getResponseBody(), OrderReceiveResponse.class).asReplay();
157	        }
158	        // 占位尚未回填（理论仅极端并发），按实体重建。
159	        CurtailOrder order = dispatchRepository.findOrderById(existing.getRefId());
160	        throw new ApiConflictException("首次请求仍在处理中");
161	    }
162	
163	    /**
164	     * 机组执行回报：按机组＋时刻去重；满 10 分钟未达标则告警并按最新可用出力重分摊。
165	     */
166	    @Transactional
167	    public ReportResponse report(ReportRequest request) {
168	        Instant now = clock.now();
169	        String fingerprint = Fingerprints.sha256(
170	                "REPORT|" + request.requestId() + "|" + request.turbineCode() + "|"
171	                        + request.measuredAt() + "|" + request.powerKw());
172	
173	        IdempotentRecord existing = idempotentRepository.findByRequestId(request.requestId());
174	        if (existing != null) {
175	            return resolveReportIdempotent(existing, fingerprint);
176	        }
177	
178	        Turbine turbine = turbineRepository.findByCode(request.turbineCode());
179	        if (turbine == null) {
180	            throw new ApiNotFoundException("机组不存在：" + request.turbineCode());
181	        }
182	
183	        // 优先归属执行中指令；无执行中指令时取最新指令用于判定封存后的迟到回报。
184	        CurtailOrder order = dispatchRepository.findActiveOrder(turbine.getFarmCode());
185	        if (order == null) {
186	            order = dispatchRepository.findLatestOrder(turbine.getFarmCode());
187	        }
188	        if (order == null) {
189	            throw new ApiBadRequestException("该风场尚无任何限电指令，无法接收回报");
190	        }
191	
192	        // 封存（或作废）后迟到回报：只登记迟到事件，不进入执行曲线。
193	        if (order.getStatus() == OrderStatus.SETTLED || order.getStatus() == OrderStatus.SUPERSEDED) {
194	            return recordLateReport(order, request, now, fingerprint);
195	        }
196	
197	        // 锁定执行中指令行，串行化同指令的并发回报：保证达标判定/告警重分摊不重入。
198	        CurtailOrder locked = dispatchRepository.lockOrderById(order.getId());
199	        if (locked.getStatus() != OrderStatus.DISPATCHED) {
200	            // 持锁期间指令状态可能已被日结/切换改变：按终态迟到回报处理。
201	            return recordLateReport(locked, request, now, fingerprint);
202	        }
203	        order = locked;
204	
205	        // 按机组＋时刻去重：不同 requestId 回报同一时刻点，返回首次结果，不重复入库。
206	        ExecutionReport samePoint =
207	                dispatchRepository.findReportByTurbineAndTime(turbine.getId(), request.measuredAt());
208	        if (samePoint != null) {
209	            CurtailPointView view = loadPointView(samePoint, turbine);
210	            return new ReportResponse(samePoint.getRequestId(), view.orderNo(), turbine.getTurbineCode(),
211	                    samePoint.getMeasuredAt().toString(), samePoint.getPowerKw(), false, true);
212	        }
213	
214	        IdempotentRecord record = newIdempotent(request.requestId(), "REPORT", fingerprint, now);
215	        if (!idempotentRepository.tryInsert(record)) {
216	            return resolveReportIdempotent(
217	                    idempotentRepository.findByRequestId(request.requestId()), fingerprint);
218	        }
219	
220	        ExecutionReport report = new ExecutionReport();
221	        report.setRequestId(request.requestId());
222	        report.setOrderId(order.getId());
223	        report.setTurbineId(turbine.getId());
224	        report.setMeasuredAt(request.measuredAt());
225	        report.setPowerKw(request.powerKw());
226	        report.setReceivedAt(now);
227	        try {
228	            dispatchRepository.insertReport(report);
229	        } catch (org.springframework.dao.DuplicateKeyException ex) {
230	            // 同机组＋时刻并发回报：唯一约束兜底，回查返回首次结果（按时刻去重）。
231	            ExecutionReport winner =
232	                    dispatchRepository.findReportByTurbineAndTime(turbine.getId(), request.measuredAt());
233	            CurtailOrder owner = winner == null ? order
234	                    : dispatchRepository.findOrderById(winner.getOrderId());
235	            ReportResponse dedup = new ReportResponse(
236	                    winner == null ? request.requestId() : winner.getRequestId(),
237	                    owner.getOrderNo(), turbine.getTurbineCode(),
238	                    request.measuredAt().toString(),
239	                    winner == null ? request.powerKw() : winner.getPowerKw(),
240	                    false, true);
241	            idempotentRepository.updateRefAndResponse(
242	                    request.requestId(), winner == null ? null : winner.getId(), toJson(dedup));
243	            return dedup;
244	        }
245	
246	        // 最新可用出力以回报实测值刷新，作为重分摊依据。
247	        turbineRepository.updateAvailablePower(turbine.getId(), request.powerKw(), now);
248	        turbine.setAvailablePowerKw(request.powerKw());
249	
250	        maybeAlertAndReallocate(order, now);
251	
252	        ReportResponse response = new ReportResponse(request.requestId(), order.getOrderNo(),
253	                request.turbineCode(), request.measuredAt().toString(), request.powerKw(),
254	                false, false);
255	        idempotentRepository.updateRefAndResponse(request.requestId(), report.getId(), toJson(response));
256	        return response;
257	    }
258	
259	    private record CurtailPointView(String orderNo) {
260	    }
261	
262	    /** 登记封存/作废后的迟到回报：幂等占位 + 迟到事件，返回 late=true。 */
263	    private ReportResponse recordLateReport(CurtailOrder order, ReportRequest request,
264	                                            Instant now, String fingerprint) {
265	        IdempotentRecord record = newIdempotent(request.requestId(), "REPORT", fingerprint, now);
266	        if (!idempotentRepository.tryInsert(record)) {
267	            return resolveReportIdempotent(
268	                    idempotentRepository.findByRequestId(request.requestId()), fingerprint);
269	        }
270	        LateReportEvent event = new LateReportEvent();
271	        event.setOrderId(order.getId());
272	        event.setTurbineCode(request.turbineCode());
273	        event.setMeasuredAt(request.measuredAt());
274	        event.setPowerKw(request.powerKw());
275	        event.setRequestId(request.requestId());
276	        event.setRecordedAt(now);
277	        dispatchRepository.insertLateReport(event);
278	        ReportResponse response = new ReportResponse(request.requestId(), order.getOrderNo(),
279	                request.turbineCode(), request.measuredAt().toString(), request.powerKw(),
280	                true, false);
281	        idempotentRepository.updateRefAndResponse(request.requestId(), null, toJson(response));
282	        return response;
283	    }
284	
285	    private CurtailPointView loadPointView(ExecutionReport report, Turbine turbine) {
286	        CurtailOrder owner = dispatchRepository.findOrderById(report.getOrderId());
287	        return new CurtailPointView(owner == null ? null : owner.getOrderNo());
288	    }
289	
290	    /**
291	     * 达标判定与重分摊：当前轮次下发恰满 10 分钟，全场最新出力仍高于目标则告警，
292	     * 并按各机组最新可用出力重分摊生成下一轮。
293	     */
294	    private void maybeAlertAndReallocate(CurtailOrder order, Instant now) {
295	        int cycleNo = order.getCurrentCycleNo();
296	        DispatchCycle cycle = dispatchRepository.findCycles(order.getId()).stream()
297	                .filter(c -> c.getCycleNo() == cycleNo)
298	                .findFirst()
299	                .orElseThrow(() -> new ApiBadRequestException("当前下发轮次缺失：" + cycleNo));
300	
301	        // 恰满 10 分钟判定：now 早于 dueAt 不触发。
302	        if (now.isBefore(cycle.getDueAt())) {
303	            return;
304	        }
305	        if (dispatchRepository.findAlert(order.getId(), cycleNo) != null) {
306	            return;
307	        }
308	
309	        List<Turbine> turbines = turbineRepository.findByFarm(order.getFarmCode());
310	        int farmActual = turbines.stream().mapToInt(Turbine::getAvailablePowerKw).sum();
311	        if (farmActual <= order.getTargetPowerKw()) {
312	            return;
313	        }
314	
315	        AlertEvent alert = new AlertEvent();
316	        alert.setOrderId(order.getId());
317	        alert.setCycleNo(cycleNo);
318	        alert.setType(AlertType.TARGET_NOT_REACHED);
319	        alert.setFiredAt(now);
320	        alert.setFarmActualKw(farmActual);
321	        dispatchRepository.insertAlert(alert);
322	
323	        int newCycleNo = cycleNo + 1;
324	        List<Allocation> reallocations =
325	                AllocationEngine.allocate(turbines, order.getTargetPowerKw(), order.getId(), newCycleNo);
326	        dispatchRepository.insertCycle(buildCycle(order.getId(), newCycleNo, now));
327	        dispatchRepository.insertAllocations(order.getId(), newCycleNo, reallocations);
328	        dispatchRepository.updateAlertReallocated(order.getId(), cycleNo, newCycleNo);
329	        dispatchRepository.updateCurrentCycle(order.getId(), newCycleNo);
330	        order.setCurrentCycleNo(newCycleNo);
331	    }
332	
333	    private ReportResponse resolveReportIdempotent(IdempotentRecord existing, String fingerprint) {
334	        if (existing == null) {
335	            throw new ApiConflictException("并发请求处理中，请重试");
336	        }
337	        if (!existing.getFingerprint().equals(fingerprint)) {
338	            throw new ApiConflictException("相同 requestId 的业务参数与首次请求不一致");
339	        }
340	        if (existing.getResponseBody() != null && !existing.getResponseBody().isBlank()) {
341	            return fromJson(existing.getResponseBody(), ReportResponse.class).asReplay();
342	        }
343	        throw new ApiConflictException("首次请求仍在处理中");
344	    }
345	
346	    /**
347	     * 日结封存：终态；已封存重复封存幂等成功。
348	     */
349	    @Transactional
350	    public SettleResponse settle(String orderNo) {
351	        CurtailOrder order = dispatchRepository.findOrderByNo(orderNo);
352	        if (order == null) {
353	            throw new ApiNotFoundException("指令不存在：" + orderNo);
354	        }
355	        if (order.getStatus() == OrderStatus.SETTLED) {
356	            return new SettleResponse(order.getId(), order.getOrderNo(),
357	                    order.getStatus().name(), order.getSettledAt(), true);
358	        }
359	        if (order.getStatus() == OrderStatus.SUPERSEDED) {
360	            throw new ApiBadRequestException("指令已被新指令作废，不能日结封存：" + orderNo);
361	        }
362	        Instant now = clock.now();
363	        dispatchRepository.markSettled(order.getId(), now);
364	        return new SettleResponse(order.getId(), order.getOrderNo(),
365	                OrderStatus.SETTLED.name(), now, false);
366	    }
367	
368	    /**
369	     * 指令详情：各轮分摊明细、按机组＋时刻归位的执行曲线、告警链与迟到事件，均可复算。
370	     */
371	    public OrderDetailResponse detail(String orderNo) {
372	        CurtailOrder order = dispatchRepository.findOrderByNo(orderNo);
373	        if (order == null) {
374	            throw new ApiNotFoundException("指令不存在：" + orderNo);
375	        }
376	        List<Turbine> turbines = turbineRepository.findByFarm(order.getFarmCode());
377	        Map<Long, Turbine> turbineById = turbines.stream()
378	                .collect(Collectors.toMap(Turbine::getId, t -> t));
379	
380	        List<DispatchCycle> cycles = dispatchRepository.findCycles(order.getId());
381	        List<Allocation> allAllocations = dispatchRepository.findAllAllocations(order.getId());
382	        List<OrderDetailResponse.CycleView> cycleViews = new ArrayList<>();
383	        for (DispatchCycle c : cycles) {
384	            List<AllocationItem> items = allAllocations.stream()
385	                    .filter(a -> a.getCycleNo() == c.getCycleNo())
386	                    .map(a -> toItem(a, turbineById.get(a.getTurbineId())))
387	                    .toList();
388	            cycleViews.add(new OrderDetailResponse.CycleView(
389	                    c.getCycleNo(), c.getDispatchedAt(), c.getDueAt(), items));
390	        }
391	
392	        List<ExecutionReport> reports =
393	                dispatchRepository.findReportsOfFarm(order.getFarmCode()).stream()
394	                        .filter(r -> r.getOrderId() == order.getId())
395	                        .toList();
396	        List<OrderDetailResponse.ReportPoint> curve = reports.stream()
397	                .map(r -> new OrderDetailResponse.ReportPoint(
398	                        turbineById.get(r.getTurbineId()).getTurbineCode(),
399	                        r.getMeasuredAt(), r.getPowerKw(), r.getReceivedAt()))
400	                .toList();
401	
402	        List<AlertView> alerts = dispatchRepository.findAlerts(order.getId())
403	                .stream()
404	                .map(a -> new AlertView(a.getCycleNo(), a.getType().name(),
405	                        a.getFiredAt(), a.getFarmActualKw(), a.getReallocatedCycleNo()))
406	                .toList();
407	
408	        List<OrderDetailResponse.LateReportView> late = dispatchRepository.findLateReports(order.getId())
409	                .stream()
410	                .map(e -> new OrderDetailResponse.LateReportView(e.getTurbineCode(),
411	                        e.getMeasuredAt(), e.getPowerKw(), e.getRequestId(), e.getRecordedAt()))
412	                .toList();
413	
414	        return new OrderDetailResponse(order.getId(), order.getOrderNo(), order.getFarmCode(),
415	                order.getRequestId(), order.getTargetPowerKw(), order.getStatus().name(),
416	                order.getCurrentCycleNo(), order.getReceivedAt(), order.getSettledAt(),
417	                cycleViews, curve, alerts, late);
418	    }
419	
420	    private OrderReceiveResponse buildReceiveResponse(CurtailOrder order, List<Turbine> turbines,
421	                                                      List<Allocation> allocations,
422	                                                      int farmAvailable, boolean replayed) {
