116	    public long insertOrder(CurtailOrder order) {
117	        KeyHolder keyHolder = new GeneratedKeyHolder();
118	        jdbc.update(connection -> {
119	            PreparedStatement ps = connection.prepareStatement("""
120	                    INSERT INTO curtail_order
121	                        (order_no, farm_code, request_id, fingerprint, target_power_kw,
122	                         status, current_cycle_no, superseded_by_order_id, active_flag,
123	                         received_at, settled_at)
124	                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
125	                    """, Statement.RETURN_GENERATED_KEYS);
126	            ps.setString(1, order.getOrderNo());
127	            ps.setString(2, order.getFarmCode());
128	            ps.setString(3, order.getRequestId());
129	            ps.setString(4, order.getFingerprint());
130	            ps.setInt(5, order.getTargetPowerKw());
131	            ps.setString(6, order.getStatus().name());
132	            ps.setInt(7, order.getCurrentCycleNo());
133	            if (order.getSupersededByOrderId() == null) {
134	                ps.setNull(8, java.sql.Types.BIGINT);
135	            } else {
136	                ps.setLong(8, order.getSupersededByOrderId());
137	            }
138	            // 新指令一律先以非执行中（active_flag=NULL）插入，由服务在旧指令作废后显式置 Y，
139	            // 保证同一事务内不会出现两个执行中指令。
140	            ps.setNull(9, java.sql.Types.CHAR);
141	            ps.setTimestamp(10, Timestamp.from(order.getReceivedAt()));
142	            ps.setTimestamp(11, order.getSettledAt() == null ? null : Timestamp.from(order.getSettledAt()));
143	            return ps;
144	        }, keyHolder);
145	        Number key = keyHolder.getKey();
146	        long id = key == null ? 0L : key.longValue();
147	        order.setId(id);
148	        return id;
149	    }
