1	package com.example.starter.service;
2	
3	import static org.assertj.core.api.Assertions.assertThat;
4	import static org.assertj.core.api.Assertions.assertThatThrownBy;
5	
6	import org.junit.jupiter.api.BeforeEach;
7	import org.junit.jupiter.api.DisplayName;
8	import org.junit.jupiter.api.Test;
9	import org.springframework.beans.factory.annotation.Autowired;
10	import org.springframework.boot.test.context.SpringBootTest;
11	
12	import com.example.starter.AbstractIntegrationTest;
13	import com.example.starter.dto.OrderDetailResponse;
14	import com.example.starter.dto.OrderReceiveRequest;
15	import com.example.starter.dto.OrderReceiveResponse;
16	import com.example.starter.dto.ReportRequest;
17	import com.example.starter.dto.ReportResponse;
18	import com.example.starter.dto.SettleResponse;
19	import com.example.starter.web.ApiBadRequestException;
20	import com.example.starter.web.ApiConflictException;
21	
22	/**
23	 * H2 事务集成测试：主流程、恰等不降机、15% 边界、尾差、乱序归位、
24	 * 10 分钟恰超时告警重分摊、封存终态与迟到回报。
25	 */
26	@SpringBootTest
27	class DispatchFlowIntegrationTest extends AbstractIntegrationTest {
28	
29	    @Autowired
30	    private DispatchService dispatchService;
31	
32	    @BeforeEach
33	    void setUp() {
34	        resetDb();
35	        pinClock(10, 0, 0);
36	    }
37	
38	    @Test
39	    @DisplayName("接收即分摊：恰等全场可用出力时不降机")
40	    void receiveExactTargetNoCurtailment() {
41	        OrderReceiveResponse resp = dispatchService.receive(
42	                new OrderReceiveRequest("req-1", FARM, 6000));
43	
44	        assertThat(resp.noCurtailment()).isTrue();
45	        assertThat(resp.curtailedKw()).isZero();
46	        assertThat(resp.allocations()).allSatisfy(a -> assertThat(a.curtailKw()).isZero());
47	        assertThat(resp.allocations()).extracting(a -> a.targetPowerKw())
48	                .containsExactly(2000, 1600, 2400);
49	        assertThat(resp.status()).isEqualTo("DISPATCHED");
50	        assertThat(resp.replayed()).isFalse();
51	    }
52	
53	    @Test
54	    @DisplayName("分摊合计恰等于目标，单机目标不低于技术下限，尾差归入最大可降机组")
55	    void allocationSumsToTargetWith15PercentFloor() {
56	        // 可降空间 1700/1300/1950；压减 1000 → 目标 5000。
57	        OrderReceiveResponse resp = dispatchService.receive(
58	                new OrderReceiveRequest("req-2", FARM, 5000));
59	
60	        assertThat(resp.allocations()).extracting(a -> a.targetPowerKw())
61	                .hasSize(3);
62	        int sum = resp.allocations().stream().mapToInt(a -> a.targetPowerKw()).sum();
63	        assertThat(sum).isEqualTo(5000);
64	        assertThat(resp.allocations()).allSatisfy(a ->
65	                assertThat(a.targetPowerKw()).isGreaterThanOrEqualTo(a.technicalMinKw()));
66	        // 尾差 1 归可降空间最大的 T-03。
67	        // 精确比例：1000*1700/4950=343, 1000*1300/4950=262, 1000*1950/4950=393；和 998，尾差 2 归 T-03。
68	        var byCode = resp.allocations().stream()
69	                .collect(java.util.stream.Collectors.toMap(a -> a.turbineCode(), a -> a));
70	        assertThat(byCode.get("T-01").curtailKw()).isEqualTo(343);
71	        assertThat(byCode.get("T-02").curtailKw()).isEqualTo(262);
72	        assertThat(byCode.get("T-03").curtailKw()).isEqualTo(395);
73	    }
74	
75	    @Test
76	    @DisplayName("目标恰为全场下限之和：三机组恰降至 15%，合法")
77	    void targetExactlyAtFloor() {
78	        OrderReceiveResponse resp = dispatchService.receive(
79	                new OrderReceiveRequest("req-3", FARM, 1050));
80	
81	        assertThat(resp.allocations()).extracting(a -> a.targetPowerKw())
82	                .containsExactly(300, 300, 450);
83	    }
84	
85	    @Test
86	    @DisplayName("同键同参重放返回首次结果；同键异参返回 409")
87	    void idempotentReplayAndConflict() {
88	        OrderReceiveRequest first = new OrderReceiveRequest("req-4", FARM, 5000);
89	        OrderReceiveResponse r1 = dispatchService.receive(first);
90	        OrderReceiveResponse r2 = dispatchService.receive(first);
91	
92	        assertThat(r2.replayed()).isTrue();
93	        assertThat(r2.orderId()).isEqualTo(r1.orderId());
94	        assertThat(r2.allocations()).isEqualTo(r1.allocations());
95	
96	        OrderReceiveRequest changed = new OrderReceiveRequest("req-4", FARM, 4999);
97	        assertThatThrownBy(() -> dispatchService.receive(changed))
98	                .isInstanceOf(ApiConflictException.class);
99	    }
100	
101	    @Test
102	    @DisplayName("乱序回报按时刻归位，且按机组＋时刻去重")
103	    void outOfOrderReportsAreSortedAndDeduplicated() {
104	        OrderReceiveResponse order = dispatchService.receive(
105	                new OrderReceiveRequest("req-5", FARM, 5000));
106	
107	        // 先报较晚时刻，再报较早时刻（乱序）。
108	        dispatchService.report(new ReportRequest("rp-2", "T-01",
109	                localInstant(10, 5, 0), 1700));
110	        dispatchService.report(new ReportRequest("rp-1", "T-01",
111	                localInstant(10, 2, 0), 1800));
112	        // 同机组＋同时刻、不同 requestId 再报：去重，返回首次结果。
113	        ReportResponse dup = dispatchService.report(new ReportRequest("rp-3", "T-01",
114	                localInstant(10, 2, 0), 1800));
115	        assertThat(dup.replayed()).isTrue();
116	        assertThat(dup.powerKw()).isEqualTo(1800);
117	
118	        OrderDetailResponse detail = dispatchService.detail(order.orderNo());
119	        assertThat(detail.executionCurve()).hasSize(2);
120	        // 按时刻归位：10:02 在 10:05 前。
121	        assertThat(detail.executionCurve().get(0).measuredAt()).isEqualTo(localInstant(10, 2, 0));
122	        assertThat(detail.executionCurve().get(1).measuredAt()).isEqualTo(localInstant(10, 5, 0));
123	    }
124	
125	    @Test
126	    @DisplayName("下发未满 10 分钟不告警；恰满 10 分钟未达标触发告警并重分摊")
127	    void alertFiresExactlyAtTenMinutesAndReallocates() {
128	        OrderReceiveResponse order = dispatchService.receive(
129	                new OrderReceiveRequest("req-6", FARM, 5000));
130	        String orderNo = order.orderNo();
131	
132	        // 10:09:59（早于 dueAt 10:10:00）全场仍高于目标，不告警。
133	        clock.pinAtLocal(java.time.LocalDateTime.of(2026, 9, 26, 10, 9, 59));
134	        dispatchService.report(new ReportRequest("rp-a", "T-01",
135	                localInstant(10, 9, 0), 1900));
136	        assertThat(dispatchService.detail(orderNo).alerts()).isEmpty();
137	        assertThat(dispatchService.detail(orderNo).currentCycleNo()).isEqualTo(1);
138	
139	        // 恰满 10 分钟 10:10:00：全场出力仍超目标 → 告警 + 重分摊（第 2 轮）。
140	        clock.pinAtLocal(java.time.LocalDateTime.of(2026, 9, 26, 10, 10, 0));
141	        dispatchService.report(new ReportRequest("rp-b", "T-01",
142	                localInstant(10, 10, 0), 1900));
143	
144	        OrderDetailResponse after = dispatchService.detail(orderNo);
145	        assertThat(after.alerts()).hasSize(1);
146	        assertThat(after.alerts().get(0).cycleNo()).isEqualTo(1);
147	        assertThat(after.alerts().get(0).reallocatedCycleNo()).isEqualTo(2);
148	        assertThat(after.currentCycleNo()).isEqualTo(2);
149	        assertThat(after.cycles()).hasSize(2);
150	        // 重分摊以最新可用出力为基准（T-01 已更新为 1900），新轮目标合计仍恰为 5000。
151	        int newCycleSum = after.cycles().get(1).allocations().stream()
152	                .mapToInt(a -> a.targetPowerKw()).sum();
153	        assertThat(newCycleSum).isEqualTo(5000);
154	        // 同一轮不重复告警。
155	        dispatchService.report(new ReportRequest("rp-c", "T-02",
156	                localInstant(10, 10, 30), 1500));
157	        assertThat(dispatchService.detail(orderNo).alerts()).hasSize(1);
158	    }
159	
160	    @Test
161	    @DisplayName("恰满 10 分钟但全场已达标：不告警")
162	    void noAlertWhenTargetReachedAtTenMinutes() {
163	        OrderReceiveResponse order = dispatchService.receive(
164	                new OrderReceiveRequest("req-7", FARM, 5000));
165	
166	        // 判定时刻前（10:09:5x）三机组已降到目标水平：1900+1200+1900=5000，此时不判超时。
167	        clock.pinAtLocal(java.time.LocalDateTime.of(2026, 9, 26, 10, 9, 50));
168	        dispatchService.report(new ReportRequest("rp-1", "T-01", localInstant(10, 9, 50), 1900));
169	        clock.pinAtLocal(java.time.LocalDateTime.of(2026, 9, 26, 10, 9, 51));
170	        dispatchService.report(new ReportRequest("rp-2", "T-02", localInstant(10, 9, 51), 1200));
171	        clock.pinAtLocal(java.time.LocalDateTime.of(2026, 9, 26, 10, 9, 52));
172	        dispatchService.report(new ReportRequest("rp-3", "T-03", localInstant(10, 9, 52), 1900));
173	
174	        // 恰满 10 分钟的回报确认：全场 4950 ≤ 目标 5000，不告警。
175	        clock.pinAtLocal(java.time.LocalDateTime.of(2026, 9, 26, 10, 10, 0));
176	        dispatchService.report(new ReportRequest("rp-4", "T-01", localInstant(10, 10, 0), 1850));
177	
178	        OrderDetailResponse detail = dispatchService.detail(order.orderNo());
179	        assertThat(detail.alerts()).isEmpty();
180	        assertThat(detail.currentCycleNo()).isEqualTo(1);
181	    }
182	
183	    @Test
184	    @DisplayName("回报同键同参重放幂等；同键异参 409")
185	    void reportIdempotentReplayAndConflict() {
186	        dispatchService.receive(new OrderReceiveRequest("req-rp", FARM, 5000));
187	        ReportRequest req = new ReportRequest(
188	                "rp-key", "T-01", localInstant(10, 2, 0), 1800);
189	
190	        ReportResponse first = dispatchService.report(req);
191	        assertThat(first.replayed()).isFalse();
192	        ReportResponse replay = dispatchService.report(req);
193	        assertThat(replay.replayed()).isTrue();
194	        assertThat(replay.powerKw()).isEqualTo(1800);
195	
196	        ReportRequest changed = new ReportRequest(
197	                "rp-key", "T-01", localInstant(10, 2, 0), 1700);
198	        assertThatThrownBy(() -> dispatchService.report(changed))
199	                .isInstanceOf(ApiConflictException.class);
200	
201	        // 幂等重放不产生重复回报点。
202	        assertThat(jdbc.queryForObject(
203	                "SELECT COUNT(*) FROM execution_report", Integer.class)).isEqualTo(1);
204	    }
205	
206	    @Test
207	    @DisplayName("目标高于全场可用出力：400（无需限电）")
208	    void targetAboveAvailableRejected() {
209	        assertThatThrownBy(() ->
210	                dispatchService.receive(new OrderReceiveRequest("req-bad", FARM, 6001)))
211	                .isInstanceOf(ApiBadRequestException.class);
212	    }
213	
214	    @Test
215	    @DisplayName("对已被作废的指令日结封存：400")
216	    void settleSupersededOrderRejected() {
217	        OrderReceiveResponse old = dispatchService.receive(
218	                new OrderReceiveRequest("req-old", FARM, 5000));
219	        pinClock(10, 5, 0);
220	        dispatchService.receive(new OrderReceiveRequest("req-new", FARM, 4500));
221	
222	        assertThatThrownBy(() -> dispatchService.settle(old.orderNo()))
223	                .isInstanceOf(ApiBadRequestException.class);
224	    }
225	
226	    @Test
227	    @DisplayName("日结封存为终态：重复封存幂等成功，封存后迟到回报只记迟到事件")
228	    void settleIsTerminalAndLateReportsRecorded() {
229	        OrderReceiveResponse order = dispatchService.receive(
230	                new OrderReceiveRequest("req-8", FARM, 5000));
231	
232	        SettleResponse s1 = dispatchService.settle(order.orderNo());
233	        assertThat(s1.status()).isEqualTo("SETTLED");
234	        assertThat(s1.replayed()).isFalse();
235	        SettleResponse s2 = dispatchService.settle(order.orderNo());
236	        assertThat(s2.replayed()).isTrue();
237	        assertThat(s2.settledAt()).isEqualTo(s1.settledAt());
238	
239	        // 封存后回报：late=true，不进执行曲线。
240	        ReportResponse late = dispatchService.report(new ReportRequest("rp-late", "T-01",
241	                localInstant(10, 20, 0), 1800));
242	        assertThat(late.late()).isTrue();
243	
244	        OrderDetailResponse detail = dispatchService.detail(order.orderNo());
245	        assertThat(detail.executionCurve()).isEmpty();
246	        assertThat(detail.lateReports()).hasSize(1);
247	        assertThat(detail.lateReports().get(0).turbineCode()).isEqualTo("T-01");
248	
249	        // 迟到回报同键重放仍幂等。
250	        ReportRequest lateReq = new ReportRequest("rp-late", "T-01",
251	                localInstant(10, 20, 0), 1800);
252	        ReportResponse lateReplay = dispatchService.report(lateReq);
253	        assertThat(lateReplay.replayed()).isTrue();
254	        assertThat(dispatchService.detail(order.orderNo()).lateReports()).hasSize(1);
255	    }
256	}
