package com.example.starter.domain;

import java.time.Instant;
import java.time.LocalDate;

/**
 * 日前计划版本（发布后不可变）。
 * farmCode + planDate（UTC 日期）唯一确定一条版本链；version 从 1 开始，每次成功发布加 1；
 * isCurrent 仅当前版本为 true，历史版本保留可查；requestId/fingerprint 为发布请求幂等证据。
 */
public class DayAheadPlan {

    private Long id;
    private String farmCode;
    private LocalDate planDate;
    private int version;
    private String requestId;
    private String fingerprint;
    private boolean current;
    private Instant publishedAt;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getFarmCode() {
        return farmCode;
    }

    public void setFarmCode(String farmCode) {
        this.farmCode = farmCode;
    }

    public LocalDate getPlanDate() {
        return planDate;
    }

    public void setPlanDate(LocalDate planDate) {
        this.planDate = planDate;
    }

    public int getVersion() {
        return version;
    }

    public void setVersion(int version) {
        this.version = version;
    }

    public String getRequestId() {
        return requestId;
    }

    public void setRequestId(String requestId) {
        this.requestId = requestId;
    }

    public String getFingerprint() {
        return fingerprint;
    }

    public void setFingerprint(String fingerprint) {
        this.fingerprint = fingerprint;
    }

    public boolean isCurrent() {
        return current;
    }

    public void setCurrent(boolean current) {
        this.current = current;
    }

    public Instant getPublishedAt() {
        return publishedAt;
    }

    public void setPublishedAt(Instant publishedAt) {
        this.publishedAt = publishedAt;
    }
}

package com.example.starter.domain;

/**
 * 日前计划明细：某版本某时段某机组的核定计划出力。
 * periodIndex 时段序号 1..96（每段 15 分钟半开区间）；plannedKw 非负且不超过机组装机容量，单位 kW。
 */
public class DayAheadPlanItem {

    private Long id;
    private Long planId;
    private int periodIndex;
    private Long turbineId;
    private int plannedKw;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Long getPlanId() {
        return planId;
    }

    public void setPlanId(Long planId) {
        this.planId = planId;
    }

    public int getPeriodIndex() {
        return periodIndex;
    }

    public void setPeriodIndex(int periodIndex) {
        this.periodIndex = periodIndex;
    }

    public Long getTurbineId() {
        return turbineId;
    }

    public void setTurbineId(Long turbineId) {
        this.turbineId = turbineId;
    }

    public int getPlannedKw() {
        return plannedKw;
    }

    public void setPlannedKw(int plannedKw) {
        this.plannedKw = plannedKw;
    }
}

package com.example.starter.domain;

/**
 * 指令计划基数证据（受理时冻结，随指令不可变）。
 * plannedKw 冻结的该段核定计划（kW）；availableKw 受理时机组实时可用出力（kW）；
 * baseKw 可参与出力 = min(availableKw, plannedKw)，限电分摊以此为基数。
 */
public class OrderPlanBase {

    private Long id;
    private Long orderId;
    private Long planId;
    private Long turbineId;
    private int plannedKw;
    private int availableKw;
    private int baseKw;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Long getOrderId() {
        return orderId;
    }

    public void setOrderId(Long orderId) {
        this.orderId = orderId;
    }

    public Long getPlanId() {
        return planId;
    }

    public void setPlanId(Long planId) {
        this.planId = planId;
    }

    public Long getTurbineId() {
        return turbineId;
    }

    public void setTurbineId(Long turbineId) {
        this.turbineId = turbineId;
    }

    public int getPlannedKw() {
        return plannedKw;
    }

    public void setPlannedKw(int plannedKw) {
        this.plannedKw = plannedKw;
    }

    public int getAvailableKw() {
        return availableKw;
    }

    public void setAvailableKw(int availableKw) {
        this.availableKw = availableKw;
    }

    public int getBaseKw() {
        return baseKw;
    }

    public void setBaseKw(int baseKw) {
        this.baseKw = baseKw;
    }
}

