package com.example.starter.dto;

import java.time.LocalDate;
import java.util.List;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;

/**
 * 日前计划发布请求。计划按风场＋UTC 日期编制，须含完整 96 个十五分钟半开时段
 * 及每台机组的非负整数 kW 计划；发布后形成不可变版本。
 *
 * @param requestId       幂等键，覆盖本对象全部业务字段
 * @param farmCode        风场编码
 * @param planDate        计划日期（UTC 日期，ISO-8601，如 2026-09-27）
 * @param expectedVersion 期望的当前版本号：0 表示尚无版本，否则须等于当前版本号；成功发布后版本加 1
 * @param turbines        每台机组的 96 段计划，须恰好覆盖风场全部机组且不重复
 */
public record PlanPublishRequest(
        @NotBlank String requestId,
        @NotBlank String farmCode,
        @NotNull LocalDate planDate,
        @Min(0) int expectedVersion,
        @NotEmpty List<@Valid TurbinePlan> turbines) {

    /**
     * 单台机组的 96 段计划。plannedKw 下标 0 对应时段 1，共 96 段，缺段/多段整版拒绝。
     *
     * @param turbineCode 机组编码（风场内唯一，列表内不得重复）
     * @param plannedKw   96 个时段的核定计划出力（kW，非负且不超过装机容量）
     */
    public record TurbinePlan(
            @NotBlank String turbineCode,
            @NotNull List<@NotNull Integer> plannedKw) {
    }
}

package com.example.starter.dto;

import java.time.Instant;
import java.time.LocalDate;

/**
 * 日前计划发布/重放响应。replayed=true 表示同键同参重放，内容与首次响应一致。
 */
public record PlanPublishResponse(
        Long planId,
        String farmCode,
        LocalDate planDate,
        int version,
        int turbineCount,
        int periodCount,
        Instant publishedAt,
        boolean replayed) {

    /** 同键同参重放时标记 replayed=true，其余内容与首次响应一致。 */
    public PlanPublishResponse asReplay() {
        return new PlanPublishResponse(planId, farmCode, planDate, version,
                turbineCount, periodCount, publishedAt, true);
    }
}

package com.example.starter.dto;

import java.time.Instant;
import java.time.LocalDate;
import java.util.List;

/**
 * 日前计划版本详情：版本号、是否当前版本与全部 96 段 × 机组明细（发布后不可变，可复算）。
 */
public record PlanVersionResponse(
        Long planId,
        String farmCode,
        LocalDate planDate,
        int version,
        boolean current,
        Instant publishedAt,
        List<PlanItemView> items) {

    /** 单条计划明细：时段序号（1..96）、机组编码与核定计划出力（kW）。 */
    public record PlanItemView(
            int periodIndex,
            String turbineCode,
            int plannedKw) {
    }
}

package com.example.starter.dto;

import java.time.Instant;
import java.time.LocalDate;
import java.util.List;

/**
 * 指令计划基数证据：受理计划绑定指令时冻结的计划版本与各机组基数，
 * 后续发布新计划不改变本证据；重复查询结果稳定。
 */
public record PlanBaseEvidenceResponse(
        Long orderId,
        String orderNo,
        Long planId,
        int planVersion,
        LocalDate planDate,
        int periodIndex,
        Instant frozenAt,
        List<BaseItem> items) {

    /**
     * 单机组冻结基数。
     *
     * @param turbineCode  机组编码
     * @param plannedKw    受理时冻结的该段核定计划出力（kW）
     * @param availableKw  受理时机组实时可用出力（kW）
     * @param baseKw       可参与出力 = min(availableKw, plannedKw)（kW）
     */
    public record BaseItem(
