    }

    private Map<String, Object> planBody(String requestId, int expectedVersion,
                                         int kw01, int kw02, int kw03) {
        return Map.of(
                "requestId", requestId,
                "farmCode", FARM,
                "planDate", "2026-09-27",
                "expectedVersion", expectedVersion,
                "turbines", List.of(
                        Map.of("turbineCode", "T-01", "plannedKw", constantPeriods(kw01)),
